import numpy as np

def make_wave(kind, n_samp=1024):
    t = np.linspace(0.0, 1.0, n_samp, endpoint=False, dtype=np.float32)
    if kind == 'bass':
        x = (0.88*np.sin(2*np.pi*t)+0.26*np.sin(6*np.pi*t)+0.14*np.sin(10*np.pi*t)+0.08*np.sin(14*np.pi*t))
        x = np.tanh(x*1.55)
    elif kind == 'chord':
        x = np.zeros_like(t)
        for k in range(1,11): x += (1.0/k)*np.sin(2*np.pi*k*t)
        x += 0.12*np.sin(2*np.pi*2*t)
        x = np.tanh(x*1.05)
    elif kind == 'lead':
        x = (0.90*np.sin(2*np.pi*t)+0.26*np.sin(4*np.pi*t)+0.18*np.sin(6*np.pi*t)+0.12*np.sin(8*np.pi*t)+0.08*np.sin(10*np.pi*t)+0.04*np.sin(12*np.pi*t))
        x = np.tanh(x*1.25)
    return x
for k in ['bass','chord','lead']:
    x=make_wave(k)
    print(k, 'first', x[0], 'last', x[-1], 'diff', x[0]-x[-1])
