import subprocess, json, re
subprocess.check_output(['ft2','call','module_load',json.dumps({'path':'/workspace/submission/tune.xm'})])

def getcell(p,r,c):
    out=subprocess.check_output(['ft2','call','pattern_get_cell',json.dumps({'pattern':p,'row':r,'channel':c})]).decode()
    m=re.search(r'"text":\s*"(.*?)"\s*}\]', out, re.S)
    txt=m.group(1).encode('utf-8').decode('unicode_escape')
    return json.loads(txt)
for r in [0,1,2,3,4,5,6,7,30,31]:
    cells=[]
    for ch in range(6):
        cell=getcell(1,r,ch)
        if cell.get('instrument',0):
            cells.append((ch,cell.get('note_name'),cell.get('instrument')))
    print('pattern1 row',r,cells)
print('pattern4 row31')
cells=[]
for ch in range(6):
    cell=getcell(4,31,ch)
    if cell.get('instrument',0):
        cells.append((ch,cell.get('note_name'),cell.get('instrument')))
print(cells)
PY"}

